"""Rebuild grounded practice content: python scripts/build_content.py /path/to/extracted/materials."""
from pathlib import Path
import sys,json,shutil,sqlite3
import numpy as np
import pandas as pd
from scipy.stats import t
root=Path(sys.argv[1]); out=Path(__file__).resolve().parents[1]/'dist'; (out/'data').mkdir(exist_ok=True)
def find(pattern): return next(root.rglob(pattern))
files={}
for key,pattern in [('songs','songs.db'),('chinook','Chinook_Sqlite.sqlite'),('etl2','*ETL_Case2_Excel.xlsx'),('etl3','*ETL_Case3_Excel.xlsx'),('etl4','*ETL_Case4_Excel.xlsx'),('pay2015','*2015payroll.csv'),('pay2016','*2016payroll.csv'),('jobs','*jobcodes.csv'),('locations','*locations.csv'),('restaurant','data.xlsm'),('film','NYC_Film_Permits.xlsx')]:
 p=find(pattern); name=key+p.suffix; shutil.copyfile(p,out/'data'/name);files[key]={'name':p.name,'path':'data/'+name,'bytes':p.stat().st_size}
# Include original instructions so students can trace the adapted exercises to course cases.
for key,pattern in [('etl_instructions','*ETL.docx'),('payroll_instructions','*IntegrateCo_Excel.docx'),('restaurant_instructions','Instructions.docx'),('pcard_instructions','*PCard.docx'),('chinook_instructions','PWC SQL.docx')]:
 p=find(pattern);name=key+p.suffix;shutil.copyfile(p,out/'data'/name);files[key]={'name':p.name,'path':'data/'+name,'bytes':p.stat().st_size}
Q=[]
def add(id,topic,title,prompt,answer,criteria,kind='text',dataset=None,**kw):
 Q.append(dict(id=id,topic=topic,title=title,prompt=prompt,answer=answer,criteria=[{'label':s,'max':m} for s,m in criteria],kind=kind,dataset=dataset,minutes=2,**kw))
def sql(id,db,title,prompt,query,ordered=False):
 c=sqlite3.connect(out/files[db]['path']); rows=c.execute(query).fetchall();c.close()
 add(id,'SQL',title,prompt,query,[('Correct result on the supplied database',10)],'sql',db,sql=query,ordered=ordered,referenceRows=len(rows),source='CS50 songs requirements' if db=='songs' else 'PWC SQL.docx')
sql('S01','songs','Explore song energy','List the name and energy of every song. Return two columns.','SELECT name, energy FROM songs;')
sql('S02','songs','Order by tempo','List song names in decreasing order of tempo. Return one column.','SELECT name FROM songs ORDER BY tempo DESC;',True)
sql('S03','songs','Longest songs','List the names of the three longest songs, longest first.','SELECT name FROM songs ORDER BY duration_ms DESC LIMIT 3;',True)
sql('S04','songs','Three simultaneous conditions','List names of songs whose danceability, energy and valence are all greater than 0.6.','SELECT name FROM songs WHERE danceability > 0.6 AND energy > 0.6 AND valence > 0.6;')
sql('S05','songs','Average tempo','Return the average tempo of all songs as a single value.','SELECT AVG(tempo) FROM songs;')
sql('S06','songs','Join songs and artists','List names of all songs by Drake. Do not assume his artist_id.','SELECT s.name FROM songs s JOIN artists a ON s.artist_id=a.id WHERE a.name=\'Drake\';')
sql('S07','songs','Average energy by artist','Return the average energy of songs by Post Malone. Do not hard-code an artist ID.','SELECT AVG(s.energy) FROM songs s JOIN artists a ON s.artist_id=a.id WHERE a.name=\'Post Malone\';')
sql('S08','songs','Find featured artists','List song names containing the text feat.','SELECT name FROM songs WHERE name LIKE \'%feat.%\';')
sql('S09','chinook','Count invoices','How many rows are in the Invoice table? Write a query returning one value.','SELECT COUNT(*) FROM Invoice;')
sql('S10','chinook','High-value invoices','Count invoices with Total greater than 20.','SELECT COUNT(*) FROM Invoice WHERE Total > 20;')
sql('S11','chinook','An exclusive interval','Count invoices with Total greater than 10 and less than 20.','SELECT COUNT(*) FROM Invoice WHERE Total > 10 AND Total < 20;')
sql('S12','chinook','Three billing countries','Count invoices billed to Brazil, Argentina or Chile. Use BillingCountry.','SELECT COUNT(*) FROM Invoice WHERE BillingCountry IN (\'Brazil\',\'Argentina\',\'Chile\');')
sql('S13','chinook','Country prefix','Count invoices whose BillingCountry starts with C.','SELECT COUNT(*) FROM Invoice WHERE BillingCountry LIKE \'C%\';')
sql('S14','chinook','Missing company names','Count customers with a non-NULL Company value.','SELECT COUNT(Company) FROM Customer;')
sql('S15','chinook','Country sales ranking','Return BillingCountry and the sum of Total for each country, highest sum first.','SELECT BillingCountry, SUM(Total) FROM Invoice GROUP BY BillingCountry ORDER BY SUM(Total) DESC;',True)
sql('S16','chinook','Price categories','Return each distinct UnitPrice and the total downloaded quantity at that price, cheapest price first.','SELECT UnitPrice, SUM(Quantity) FROM InvoiceLine GROUP BY UnitPrice ORDER BY UnitPrice;',True)
sql('S17','chinook','Albums actually downloaded','Count the distinct AlbumId values for tracks appearing in InvoiceLine.','SELECT COUNT(DISTINCT t.AlbumId) FROM Track t JOIN InvoiceLine i ON t.TrackId=i.TrackId;')
sql('S18','chinook','Invoice date range','Return the earliest and latest InvoiceDate in two columns.','SELECT MIN(InvoiceDate), MAX(InvoiceDate) FROM Invoice;')
E='Analytics_mindset_case_studies_ETL.docx'
add('E01','Excel & ETL','Extract a country code','In Case 2, A2 contains JAP1080-19M. Write a formula that extracts the three-character location code and state the result.','=LEFT(A2,3) returns JAP.',[('Reusable formula extracts first three characters',6),('Correct result JAP',4)],dataset='etl2',source=E)
add('E02','Excel & ETL','Extract a variable-length plant ID','In Case 2, A2 contains JAP1080-19M. Write a formula that extracts the plant ID between the dash and the final pay-period letter. State the result.','=MID(A2,FIND("-",A2)+1,LEN(A2)-FIND("-",A2)-1) returns 19. Other correct formulas accepted.',[('Finds dash dynamically',4),('Excludes final pay-period letter',4),('Correct result 19',2)],dataset='etl2',source=E)
add('E03','Excel & ETL','Construct a composite identifier','Location is in D2 and PlantID is in F2. Write a formula producing Location-PlantID, such as JAP-19.','=D2&"-"&F2',[('Combines correct cells',6),('Uses hyphen separator',4)],dataset='etl2',source=E)
add('E04','Excel & ETL','Avoid fixed-width extraction','Case 3 uses codes such as Japan177-3Mo and AUS551-2Mo. Explain why LEFT(A2,3) is unsuitable for extracting the location in every row, and describe a repeatable alternative.','Country codes vary in length. Locate the first numeric character, then take all characters before it (e.g. LEFT with MIN/FIND over digits). Test across all country codes; do not hard-code each row.',[('Identifies variable-length codes and failure on Japan',5),('Reusable first-digit extraction method',5)],dataset='etl3',source=E)
add('E05','Excel & ETL','Standardise pay periods','In Case 3, W and We both mean weekly; M and Mo both mean monthly. Describe how to standardise these values without altering the original EmployeeCode.','Create a derived PayPeriod field, extract trailing letters, map W/We to Weekly and M/Mo to Monthly. Retain original code, flag unexpected values.',[('Correctly maps both pairs',5),('Derived field and validation of unexpected codes',5)],dataset='etl3',source=E)
add('E06','Excel & ETL','Join on the right key','Case 4 reuses PreparerID across business units. Explain how to attach the correct PreparerName to a journal line, and why matching only PreparerID is unsafe.','Match both BusinessUnitID and PreparerID using a composite-key or multi-criteria lookup. PreparerID alone is not unique and may return the wrong employee. Validate unmatched and duplicate keys.',[('Uses both key fields',5),('Explains non-uniqueness and checks matches',5)],dataset='etl4',source=E)
add('E07','Excel & ETL','A lookup to the left','In Case 4, ChartOfAccounts contains GLAccountName in column A and GLAccountNumber in column B, rows 2:86. A journal line has GLAccountNumber in B2. Write a formula to return the account name.','=INDEX(ChartOfAccounts!$A$2:$A$86,MATCH(B2,ChartOfAccounts!$B$2:$B$86,0)) or equivalent exact-match XLOOKUP.',[('Matches GLAccountNumber exactly',5),('Returns GLAccountName using reusable ranges',5)],dataset='etl4',source=E)
add('E08','Excel & ETL','Check an ETL join','After adding reference data to the 789 journal lines in Case 4, what checks would you perform before using the joined file?','Reconcile row count to 789, check no one-to-many join duplication, reconcile Amount/debit/credit totals, investigate missing reference matches and duplicate reference keys.',[('Row count and duplicate-key checks',5),('Reconciles amounts and investigates unmatched rows',5)],dataset='etl4',source=E)
I='Analytics_mindset_case_studies_IntegrateCo_Excel.docx'
add('P01','Payroll & audit','Make wages comparable','Explain how to make the 2015 and 2016 payroll wage fields comparable in IntegrateCo.','2015 gross wages = Reg_Pay + OT_Pay; 2016 uses Gross_Wages. Map Emp_No to Employee_Number, aggregate to common employee/job/half-year level; retain year. Do not double count overtime.',[('Correct gross-wage mapping without double counting',5),('Common aggregation and stable employee identifier',5)],dataset='pay2015',source=I)
add('P02','Payroll & audit','Preserve job codes','Why should job code 001 be retained as text, and why is treating the entire 2015 Job field as the job code incorrect?','Three-character text preserves leading zeros. Job includes project year, optional department, three-digit job code and optional location. Extract the code and validate against 001–012.',[('Leading-zero preservation',4),('Explains compound field and extracts/validates code',6)],dataset='jobs',source=I)
add('P03','Payroll & audit','Monthly comparisons','Can the provided 2016 payroll file support an actual monthly wage comparison with 2015? Explain.','No: 2016 has no dates and is aggregated by employee/project/department/location. A monthly allocation based on 2015 is an estimate with an explicit stable-seasonality assumption, not observed monthly 2016 wages.',[('Recognises missing dates and different granularity',5),('Distinguishes estimated allocation and its assumption',5)],dataset='pay2016',source=I)
add('P04','Payroll & audit','Zero-hour observations','How would you handle job codes with no wages or hours in one year when preparing the overall job-code table and comparing pay per hour?','Retain all valid job codes in the overall table using the job-code reference list. Avoid division by zero; display N/A or explain IFERROR. Do not interpret absent comparable hours as a real zero wage rate.',[('Retains all valid reference job codes',5),('Handles zero denominator and comparability',5)],dataset='jobs',source=I)
p16=pd.read_csv(find('*2016payroll.csv'),sep='|');mask=p16.Employee_Number.isna()
for id,title,prompt,value,tol in [('P05','Missing employee numbers','How many 2016 payroll rows have a missing Employee_Number? Enter a number.',int(mask.sum()),0),('P06','Wages without an employee number','What is the sum of Gross_Wages for 2016 rows with missing Employee_Number? Round to two decimals.',round(float(p16.loc[mask,'Gross_Wages'].sum()),2),.01)]:
 add(id,'Payroll & audit',title,prompt,str(value),[('Correct result from supplied payroll file',10)],'number','pay2016',value=value,tolerance=tol,source=I)
add('A01','Payroll & audit','P-card red flags','An OSU cardholder makes two same-day purchases from the same vendor: $3,100 and $2,400. Explain a useful audit test and the conclusion you can draw from this pattern.','Group by cardholder, vendor and date; identify multiple purchases each below $5,000 but with combined amount above $5,000. Here combined amount is $5,500. Flag possible split purchasing; examine receipts, purpose and approvals before concluding intent or a violation.',[('Correct grouping and threshold test',5),('5500 total and cautious evidence-based conclusion',5)],source='Analytics_mindset_case_studies_PCard.docx')
add('A02','Payroll & audit','Design a prohibited-purchase test','Describe how you would search OSU P-card transactions for prohibited gift cards and explain why a keyword match alone is insufficient evidence of a violation.','Search Description/Vendor/MCC for relevant gift-card indicators, account for spelling and wording, review invoices and business purpose. Keyword hits may be false positives and misses may be false negatives; a red flag is not a proven violation.',[('Uses relevant fields and documented screening logic',5),('Explains limitations and corroborating evidence',5)],source='Analytics_mindset_case_studies_PCard.docx')
# OLS models computed from actual daily aggregated restaurant data, not invented coefficient examples.
w=pd.read_excel(find('data.xlsm'),sheet_name=None)
daily=w['salesData'].groupby('date',as_index=False)[['netTotal','netTotal_364']].sum().merge(w['weatherData'],on='date',how='left').merge(w['gameData'][['date','gameDay']],on='date',how='left'); daily['gameDay']=daily.gameDay.fillna(0);daily['interaction']=daily.netTotal_364*daily.gameDay
models=[]
for mid,cols in [('basic',['tmax','gameDay']),('interaction',['netTotal_364','gameDay','interaction'])]:
 d=daily.dropna(subset=['netTotal']+cols);X=np.column_stack([np.ones(len(d)),d[cols].values]);y=d.netTotal.values;b=np.linalg.lstsq(X,y,rcond=None)[0];res=y-X@b;df=len(y)-X.shape[1];cov=(res@res/df)*np.linalg.inv(X.T@X);se=np.sqrt(np.diag(cov));p=2*t.sf(abs(b/se),df);r2=1-res@res/((y-y.mean())@(y-y.mean()))
 models.append(dict(id=mid,n=len(d),r2=float(r2),outcome='Daily aggregated netTotal (currency units)',terms=[dict(term=n,estimate=float(v),se=float(s),p=float(z)) for n,v,s,z in zip(['Intercept']+cols,b,se,p)],notes='OLS on daily sums of netTotal and netTotal_364. Joined by date to weather; absent game dates coded gameDay=0. tmax uses the units in the supplied workbook. Conventional OLS standard errors; no causal identification.'))
b=models[0]['terms'];pred=b[0]['estimate']+60*b[1]['estimate']+b[2]['estimate']
add('R01','Regression','Predict daily sales','Using the displayed basic model, predict daily netTotal when tmax=60 and gameDay=1. Enter a number rounded to two decimals.',str(round(pred,2)),[('Correct intercept plus both predictor contributions',10)],'number','restaurant',value=round(pred,2),tolerance=.02,model='basic',source='Restaurant/Instructions.docx; OLS recalculated from data.xlsm')
add('R02','Regression','Interpret temperature','Interpret the tmax coefficient in the basic model, keeping its units and the other variable in mind.',f"A one-unit increase in tmax is associated with a {b[1]['estimate']:.4f} currency-unit change in predicted daily netTotal, holding gameDay constant. Association, not proof of causation.",[('Correct direction, magnitude and units',5),('Holds gameDay constant and avoids causal overclaim',5)],dataset='restaurant',model='basic',source='Restaurant/Instructions.docx; OLS recalculated from data.xlsm')
add('R03','Regression','Interpret a game-day indicator','Interpret the gameDay coefficient in the basic model and identify its reference group.',f"At the same tmax, a game day (1) has predicted daily sales {b[2]['estimate']:.4f} currency units different from a non-game day (0). This is conditional association.",[('Correct game vs non-game comparison and coefficient',6),('Holds temperature constant; avoids causal assertion',4)],dataset='restaurant',model='basic',source='Restaurant/Instructions.docx; OLS recalculated from data.xlsm')
add('R04','Regression','Significance and business importance','Using the basic model, assess tmax at a 5% significance level. Explain what its p-value does and does not establish.',f"tmax p={b[1]['p']:.6g}. Compare with .05 to decide rejection of zero coefficient under model assumptions. A p-value is not probability the null is true, not an effect size, and not proof of causality. Economic relevance depends on coefficient magnitude and context.",[('Correct decision using displayed p-value and 5% threshold',5),('Distinguishes statistical, economic and causal interpretation',5)],dataset='restaurant',model='basic',source='Restaurant/Instructions.docx; practice adaptation')
bi=models[1]['terms'];slope=bi[1]['estimate']+bi[3]['estimate']
add('R05','Regression','Interpret an interaction','In the interaction model, state the slope on netTotal_364 for non-game days and game days, and explain the interaction coefficient.',f"Non-game slope={bi[1]['estimate']:.6f}; game-day slope={slope:.6f}. Interaction coefficient={bi[3]['estimate']:.6f} is difference between those slopes; it is not a constant overall game-day effect.",[('Correct two conditional slopes',6),('Interaction interpreted as slope difference',4)],dataset='restaurant',model='interaction',source='Restaurant/Instructions.docx; OLS recalculated from data.xlsm')
add('R06','Regression','Communicate forecast uncertainty','Bob wants a forecast seven days ahead. Explain why a fitted value from these restaurant models alone is insufficient, and what else you would communicate.','Need future predictor values or explicit assumptions. Report prediction uncertainty, model limits and out-of-sample/time-aware validation. Residual variability and future predictor uncertainty remain; high R-squared does not guarantee accuracy. Observed relationships are not necessarily causal.',[('Future inputs or explicit assumptions required',5),('Prediction uncertainty and time-aware validation',5)],dataset='restaurant',model='basic',source='Restaurant/Instructions.docx; practice adaptation')
add('R07','Regression','Prepare daily regression data','Explain how to merge the restaurant sales, weather and game data without accidentally duplicating observations or inflating sales totals.','Aggregate product-level sales to one daily netTotal first; verify one row per date in weather and games; join by date; code missing game flags as zero only after confirming the game list is complete. Check daily uniqueness, missing weather and reconciled sales totals.',[('Common daily granularity and valid date joins',5),('Uniqueness, missing data and reconciliation checks',5)],dataset='restaurant',source='Restaurant/Instructions.docx')
